---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Citation hover card: Hover a citation to see the exact passage it came from.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change citation-hover-card.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './citation-hover-card.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="citation-hover" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="chx">
  <p class="msg chx-p">Teams that show the annual price first see higher paid conversion<button class="chx-c" data-i="0">1</button>, and the effect is stronger when the monthly price stays visible beside it<button class="chx-c" data-i="1">2</button>. Your own data shows the same pattern since the September update<button class="chx-c" data-i="2">3</button>.</p>
  <div class="chx-card panel keep" role="dialog" aria-label="Source"><div class="chx-in"></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './citation-hover-card.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Citation hover card ---------- */
/* an answer with numbered citations; pointing at one (or focusing or tapping it) shows its source in a card that opens over
   the stage from the citation, below it when there is room and above it when there isn't (placePop), so it is never cut off.
   No room is kept for the card under the answer (owner, 17 Nov): the answer sits centred on its own */
.chx{position:relative;overflow:visible}
.chx-p{line-height:1.8}
/* a citation is a small grey number; pointed at or open, it takes the accent tint with the accent's text (owner: highlights
   are the tint, never a solid accent fill) */
.chx-c{display:inline-grid;place-items:center;min-width:18px;height:18px;padding:0 5px;margin:0 1px 0 3px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-hover);color:var(--dm-fg2);font-size:11px;font-variant-numeric:tabular-nums;vertical-align:2px;transition:background .2s,color .2s}
.chx-c.on{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
:root:not([data-style="soft"],[data-style="clean"]) .chx-c.on:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){background:var(--dm-bp-pick)}
@media (hover:hover) and (pointer:fine){.chx-c:hover{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}}
/* hidden as well as clear when put away, so Tab never lands on its link; it grows out of its citation's side */
.chx-card{position:absolute;left:0;top:0;width:min(290px,calc(100% - 8px));padding:var(--dm-s-4);opacity:0;visibility:hidden;pointer-events:none;z-index:4;box-shadow:var(--dm-shadow-pop);transform-origin:var(--dm-origin,top left);transition:opacity .16s ease-out,visibility 0s .16s}
.chx-card.show{opacity:1;visibility:visible;pointer-events:auto;animation:chxin .5s var(--dm-ease) both;transition-property:opacity}
@keyframes chxin{from{opacity:0;transform:translateY(10px) scale(.985);filter:blur(3px)}60%{filter:blur(0)}to{opacity:1;transform:none;filter:none}}
.chx-sh{display:flex;align-items:center;gap:var(--dm-s-2);font-size:12px;color:var(--dm-muted)}
/* the source's mark is a vivid fill of its own with white letters (owner, 18 Nov), or an avatar colour with its own ink */
.chx-sh .fv{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));display:grid;place-items:center;font-size:9px;font-weight:500;color:#fff;flex:none}
.chx-t{font-size:13px;font-weight:500;margin:var(--dm-s-2) 0 6px}
/* the passage, with a neutral rule down its left (lines are grey unless they mean something) and the part the answer relies
   on in the accent's tint */
.chx-q{font-size:12.5px;line-height:1.55;color:var(--dm-fg2);padding-left:10px;box-shadow:inset 2px 0 0 var(--dm-faint)}
.chx-q mark{background:var(--dm-sel);color:var(--dm-accent-fg,var(--dm-accent));border-radius:var(--dm-r-tiny,3px);padding:0 2px}
/* the source's foot sits under a hairline in Soft and Blueprint (owner, 21 Nov), 12px from it on each side */
.chx-f{display:flex;align-items:center;justify-content:space-between;margin-top:var(--dm-s-3);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;color:var(--dm-muted)}
/* Clean: the source's foot is the card's off-white foot strip (owner, 21 Nov), its words 16px in */
:root[data-style="clean"] .chx-f,:root [data-style="clean"] .chx-f,:root [data-style="clean"].chx-f{margin:var(--dm-s-3) -16px -16px;padding:calc(var(--dm-strip-y) + 5px) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card);line-height:18px}
.chx-f a{color:var(--dm-accent-fg,var(--dm-accent));display:inline-flex;align-items:center;gap:var(--dm-s-1);text-decoration:none}
@media (hover:hover) and (pointer:fine){.chx-f a:hover{text-decoration:underline;text-underline-offset:2px}}
/* Clean (owner, 17 and 18 Nov): the card's content 16px from each edge; it scales and fades from its citation like Clean's
   menus, and the source's mark is Clean's neutral grey */
:root[data-style="clean"] .chx-card.show,:root [data-style="clean"] .chx-card.show,:root [data-style="clean"].chx-card.show{animation:chxclean var(--dm-t) var(--dm-ease) both}
@keyframes chxclean{from{opacity:0;transform:scale(.96)}to{opacity:1;transform:none}}
:root[data-style="clean"] .chx-sh .fv,:root [data-style="clean"] .chx-sh .fv,:root [data-style="clean"].chx-sh .fv{background:var(--dm-chip)!important;color:var(--dm-fg2)!important;box-shadow:inset 0 0 0 1px var(--dm-hair)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, placePop } from '../core/core.js';
DM.def('citation-hover', (r, c) => {
  const S = [
    ['B','var(--dm-av-b)','baymard.com','Pricing page UX benchmark','Of 64 SaaS sites tested, those leading with the annual plan saw <mark>a 12 to 20% higher trial to paid rate</mark> than monthly first layouts.','Read 4 days ago'],
    ['C','var(--dm-av-r)','cxl.com','Price anchoring in plan selection','When the monthly price stayed visible with a strike through, <mark>annual selection rose by a further 9 points</mark> in the anchored group.','Read 4 days ago'],
    ['CSV','var(--dm-av-l)','Drive','Q3 conversion export.csv','Rows 412 to 480: <mark>trial to paid moves from 18.6% to 26.3%</mark> between Sep 18 and Oct 17.','Your file']
  ];
  const card = $('.chx-card', r), inn = $('.chx-in', r), box = $('.chx', r), cites = $$('.chx-c', r);
  let cur = null, hideT, showT, back = false;
  /* the card exists only while a citation (or the card itself) is under the pointer */
  function show(b){
    clearTimeout(hideT); if (cur === b) return;
    const s = S[+b.dataset.i]; cur = b;
    cites.forEach(x => x.classList.toggle('on', x === b));
    inn.innerHTML = `<div class="chx-sh"><span class="fv" style="background:${s[1]};color:${s[1].replace(')', '-ink)')}">${s[0][0]}</span><span>${s[2]}</span></div><div class="chx-t">${s[3]}</div><div class="chx-q">${s[4]}</div><div class="chx-f"><span>${s[5]}</span><a href="#" onclick="return false">Open source ${I('ext','xs')}</a></div>`;
    /* restart the entry each time, so it always grows in place and never slides sideways. It opens below its citation when
       it fits there and above it when it doesn't (placePop), so the stage or the page never cuts it off, and it stays inside
       the answer's column */
    card.classList.remove('show'); void card.offsetWidth;
    placePop(b, card);
    card.style.left = Math.max(0, Math.min(parseFloat(card.style.left) || 0, box.clientWidth - card.offsetWidth)) + 'px';
    card.classList.add('show');
  }
  function hide(now){
    clearTimeout(hideT); clearTimeout(showT);
    const go = () => { card.classList.remove('show'); cur = null; cites.forEach(x => x.classList.remove('on')); };
    if (now) go(); else hideT = setTimeout(go, 140);
  }
  /* pointing at a citation shows its card, leaving it (and the card) hides it; focus shows it too, so the keyboard gets the
     same card. Touch has no hover: a tap shows the card, the next tap anywhere else hides it */
  const hover = e => e.pointerType !== 'touch';
  cites.forEach(b => {
    c.on(b, 'pointerenter', e => { if (!hover(e)) return; clearTimeout(showT); clearTimeout(hideT); showT = setTimeout(() => show(b), cur ? 0 : 90); });
    c.on(b, 'pointerleave', e => { if (!hover(e)) return; clearTimeout(showT); hide(); });
    c.on(b, 'focus', () => { if (back){ back = false; return; } show(b); }); c.on(b, 'blur', e => { if (!card.contains(e.relatedTarget)) hide(); });
    // Enter or Space opens the card with the focus on its link, so the keyboard can reach it; Escape brings the focus back
    c.on(b, 'click', e => { if (cur !== b) show(b); if (e.isTrusted && !e.detail){ const a = $('a', card); if (a) a.focus({ preventScroll:true }); } });
  });
  c.on(card, 'pointerenter', () => clearTimeout(hideT));
  c.on(card, 'pointerleave', e => { if (hover(e)) hide(); });
  c.on(card, 'focusout', e => { if (cur && !card.contains(e.relatedTarget) && e.relatedTarget !== cur) hide(); });
  /* Escape puts the card away while the focus or the pointer is on the answer, and leaves the focus where it was, or on its
     citation when it was in the card */
  c.on(document, 'keydown', e => { if (e.key === 'Escape' && cur && (box.contains(document.activeElement) || box.matches(':hover'))){ e.preventDefault(); const to = card.contains(document.activeElement) && cur; hide(true); if (to){ back = true; to.focus({ preventScroll:true }); } } });
  c.on(document, 'pointerdown', e => { if (!card.contains(e.target) && !e.target.closest('.chx-c')) hide(true); });
  c.on(window, 'resize', e => { if (e.isTrusted) hide(true); });
  c.offs.push(() => { clearTimeout(hideT); clearTimeout(showT); });
  // the preview shows one card on its own after the entrance, then puts it away, unless you are already pointing at a citation
  let mine = false; c.on(r, 'pointerover', e => { if (e.isTrusted) mine = true; }, true);
  c.run(async () => { await c.wait(1400); if (mine || cur) return; show(cites[0]); await c.wait(2800); if (!mine && cur === cites[0]) hide(); });
});
